[1475] = { en = "Into The Temple of Atal'Hakkar", tier = 4,
  t = "De Temple of Atal'Hakkar in",
  d = "Volgens de legende is The Temple of Atal'Hakkar een heilig heiligdom voor de oude god Hakkar the Soulflayer. Het wordt onderhouden door een wrede trollenstam, de Atal'ai. Men zegt dat de tempel onneembaar is.$b$bNu de tempel onder de Pool of Tears is gezonken, is het nog moeilijker om er voorwerpen uit te halen. Maar dat is precies wat ik van je vraag, $n.$b$bHelp me door de onbeschadigde Atal'ai-tabletten te verzamelen. Breng ze naar mij, dan keer ik als held terug naar de Explorers' Guild. Samen delen we de roem.",
  o = "Verzamel 10 Atal'ai Tablets voor Brohann Caskbelly in Stormwind.",
  p = "Nu de avond langzaam over mijn loopbaan valt, wend ik me tot jou, $n. Help me met mijn laatste opdracht voor de Explorers' League. Als mijn oude botten de kracht hadden om de Swamp of Sorrows en de gezonken tempel te trotseren, zou ik naast je vechten.$b$bMijn trots maakt het moeilijk om je te vragen de Atal'ai Tablets te verzamelen. Maar mijn hoge leeftijd dwingt me ertoe.$b$bHelp me alsjeblieft, $n. Ik wil met pensioen gaan bij de Explorers' League nadat ik hun laatste opdracht heb voltooid.",
  c = "De Atal'ai Tablets! Dank je, $n!$b$bAls ik deze aan de Explorers' League geef, gaan onze namen samen de geschiedenis in. Je hebt een oude dwerg geholpen zijn laatste plicht in het leven te vervullen. Daarvoor ben ik je eeuwig dankbaar.",
  g = { {"legende", "legend"}, {"heiligdom", "shrine, sanctuary"}, {"onderhouden", "maintained (onderhouden)"}, {"wrede", "vicious, cruel (wreed)"}, {"onneembaar", "impenetrable"}, {"gezonken", "sunk (zinken)"}, {"onbeschadigde", "intact, undamaged (onbeschadigd)"}, {"roem", "glory, fame"}, {"loopbaan", "career"}, {"wend ik me tot", "I turn to (zich wenden tot)"}, {"botten", "bones (bot)"}, {"trotseren", "to brave, to defy"}, {"trots", "pride"}, {"dwingt", "forces (dwingen)"}, {"met pensioen gaan", "to retire"}, {"plicht", "obligation, duty"}, {"eeuwig", "eternally"} },
