[8417] = { en = "A Troubled Spirit", tier = 4,
  t = "Een gekwelde geest",
  d = "In de Blasted Lands is een gekwelde geest. Ooit was hij een grote held van de Horde. De eer van een krijger sterft niet met het lichaam. Het zou goed voor je zijn om met hem te praten.",
