[3446] = { en = "Into the Depths", tier = 4,
  t = "De diepte in",
  d = "In de tempel vond ik een ronde ruimte met zes balkons. Op de rand van elk balkon staat een slangenbeeld. Ik was nieuwsgierig en duwde tegen een van de beelden om te zien wat er zou gebeuren. Het was een val! Door de ontploffing viel ik bijna dood. Toen ik daar op de richel lag, keek ik naar beneden. Ik zag dat er nog een beeld onderaan in de ruimte stond; een soort altaar... Hakkar, heette het volgens mij.$B$BIk denk dat dit altaar het geheim is. Je moet dit muntstuk naar het altaar in de Sunken Temple brengen.",
  o = "Vind het Altar of Hakkar in de Sunken Temple in de Swamp of Sorrows.",
  p = "Als je het beeld bekijkt, zie je een uitholling in de zijkant. Die is precies zo groot als het muntstuk dat Marvon je gaf...",
  c = "Je duwt de stenen schijf in de opening en je hoort hem vastklikken.$B$BNu de steen op zijn plek zit, kun je verder... maar wat moet je nu doen?$B$BMisschien moet je dit altaar beter bekijken...$b",
  g = { {"diepte", "depths"}, {"balkons", "balconies (balkon)"}, {"rand", "edge"}, {"slangenbeeld", "serpent statue"}, {"nieuwsgierig", "curious"}, {"val", "trap"}, {"ontploffing", "explosion"}, {"richel", "ledge"}, {"altaar", "altar"}, {"muntstuk", "token, coin"}, {"uitholling", "depression, hollow"}, {"zijkant", "side"}, {"schijf", "disc, circle"}, {"vastklikken", "to lock/click into place"} },
},

[3447] = { en = "Secret of the Circle", tier = 4,
  t = "Het geheim van de cirkel",
  d = "Mijn herinneringen zijn vaag, maar ik vertel je wat ik kan. De cirkel van beelden in de Sunken Temple is gevaarlijk. Toch denk ik dat ze het geheim bevatten om een nog grotere schat te openen.$B$BVanaf het grote altaar kon ik een reeks lichten aanzetten. Als jij kunt ontdekken wat die lichten betekenen, kun je misschien de geheimen openen die in deze ruimte verborgen zijn.$B$BMaar ik waarschuw je, $N. In de tempel huist groot kwaad. Alles wat waardevol is, wordt waarschijnlijk fel bewaakt...",
  o = "Reis naar de Sunken Temple en ontdek het geheim dat verborgen is in de cirkel van beelden.",
  c = "Het oog van het afgodsbeeld glinstert fel, zelfs in het halfdonker van de tempel. Omdat het doorzichtig is, zie je er iets glimmends achter. Je schuift het opzij, steekt je hand erin en pakt wat er in het beeld ligt.$B$BDe schat van de Atal'ai is nu van jou.",
  g = { {"herinneringen", "memories (herinnering)"}, {"vaag", "cloudy, vague"}, {"bevatten", "to hold, to contain"}, {"schat", "treasure"}, {"reeks", "series"}, {"aanzetten", "to activate, to switch on"}, {"verborgen", "hidden"}, {"waarschuw", "warn (waarschuwen)"}, {"huist", "dwells, lives (huizen)"}, {"fel", "fiercely; brightly"}, {"afgodsbeeld", "idol"}, {"halfdonker", "half-darkness"}, {"doorzichtig", "transparent"}, {"glimmends", "shiny (glimmend)"}, {"opzij", "aside, to the side"} },
},

[4143] = { en = "Haze of Evil", tier = 4,
  t = "Nevel van het kwaad",
  d = "Eerlijk gezegd, $N, heb ik op mijn reizen nog nooit zulke planten gezien. Misschien moet ik eens een reis naar die krater maken...$B$BHoe dan ook, ik denk dat ik precies weet wat Muigin zoekt: Atal'ai-nevel. Het is vreselijk spul en moeilijk te verzamelen. Maar het is precies wat hij nodig heeft om die kleine monsters onder controle te houden.$B$BJe moet naar de tempel van Atal'Hakkar in de Swamp of Sorrows. Je kunt Atal'ai Haze verzamelen van de Deep Lurkers, Murk Worms of slijmwezens die daar leven. Succes, $N!",
  o = "Verzamel 5 monsters Atal'ai Haze en ga terug naar Muigin in Un'Goro Crater.",
  p = "Larion praat nog steeds niet met me! Hij weet echt hoe je wrok moet koesteren.",
  c = "Ik geef toe dat ik dat spul liever niet aanraak, $N! Maar als Gregan zegt dat het werkt, dan wil ik het wel proberen!",
  g = { {"nevel", "haze, mist"}, {"eerlijk gezegd", "to tell you the truth"}, {"hoe dan ook", "at any rate, anyway"}, {"vreselijk", "horrid, terrible"}, {"spul", "stuff"}, {"onder controle te houden", "to keep under control"}, {"slijmwezens", "oozes (slijmwezen)"}, {"monsters", "samples (monster)"}, {"wrok", "grudge (wrok koesteren: to hold a grudge)"}, {"geef toe", "admit (toegeven)"}, {"aanraak", "touch (aanraken)"} },
},

[8151] = { en = "The Hunter's Charm", tier = 4,
  t = "De talisman van de jager",
  d = "Ogtinc uit Azshara zoekt ervaren jagers zoals jij. Hij is een furbolg-jager die zijn stam heeft verlaten om de Cenarion Circle te helpen. Met zijn lessen wil hij de wijsheid vergroten van anderen met hetzelfde vak. Hij wil hen ook leren om het evenwicht te bewaren. Het zou goed voor je zijn om met hem te praten.$b$bOgtinc woont boven op de kliffen van Azshara, ten noordoosten van de Ruins of Eldarath.",
  o = "Spreek met Ogtinc in Azshara.",
  c = "Mijn doel is niet meer om te jagen, maar om de $C les te geven. Dat is wat het lot mij heeft gegeven.$B$BMaak samen met mij een talisman van een $C: een verzameling trofeeën van gevallen prooi. Die zal je herinneren aan je beproevingen en overwinningen van vroeger. Uiteindelijk houd ik de talisman zelf, maar ik beloon je met iets anders.",
