},

[8153] = { en = "Courser Antlers", tier = 4,
  t = "Het gewei van de courser",
  d = "De courser heeft het machtigste gewei van alle bekende landen. Met dat gewei verdedigt de courser zich. Hij doorboort een aanvaller, en vaak beschadigt hij daarbij de punten. Een volmaakt, natuurlijk gewei is het teken van een dierengeest met een enorm zelfvertrouwen.$b$bAls je zo'n gewei vasthoudt, krijg jij hetzelfde zelfvertrouwen.$b$bJaag op de mosshoof courser, vind het volmaakte gewei en breng het naar mij.",
  o = "Breng een paar Perfect Courser Antlers naar Ogtinc in Azshara. Ogtinc woont boven op de kliffen ten noordoosten van de Ruins of Eldarath.",
  p = "Heb je het gewei gevonden?",
  c = "Je moet scherpe ogen en veel geduld hebben om dit te krijgen. Goed gedaan.",
  g = { {"gewei", "antlers"}, {"machtigste", "mightiest (machtig)"}, {"verdedigt", "defends (verdedigen)"}, {"doorboort", "gores, pierces (doorboren)"}, {"aanvaller", "attacker"}, {"beschadigt", "damages (beschadigen)"}, {"volmaakt", "perfect, flawless"}, {"zelfvertrouwen", "self-confidence"}, {"vasthoudt", "hold (vasthouden)"}, {"scherpe", "keen, sharp (scherp)"}, {"geduld", "patience"} },
