[8231] = { en = "Wavethrashing", tier = 4,
  t = "Golfslagers",
  d = "De wavethrasher is een amfibisch beest dat alleen hier in Azshara leeft. Ze zijn sterk en taai.$b$bDe harde, glanzende schubben van een wavethrasher weerspiegelen de kracht van de jager.$b$bVolg en jaag op wavethrashers langs de kust van Azshara, en breng me hun schubben.",
