[8232] = { en = "The Green Drake", tier = 4,
  t = "De groene draak",
  d = "Nu stuur ik je op een gevaarlijke jacht. Dood de groene draak Morphaz en breng zijn tand naar mij. Morphaz woont diep in de Temple of Atal'Hakkar. De ingang ligt in de Swamp of Sorrows.$b$bAls je hem wilt verslaan, moet je niet alleen gaan. Deze draak heeft veel vijanden. Zoek anderen die hem willen vernietigen.$b$bDe tand van de draak staat voor de kracht die een jager vindt in het gezelschap van anderen. Breng hem naar mij, dan heb je veel geleerd.",
  o = "Breng de Tooth of Morphaz naar Ogtinc in Azshara. Ogtinc woont boven op de kliffen ten noordoosten van de Ruins of Eldarath.",
  p = "Ik zie wijsheid in je ogen, $N. Is je jacht voorbij?",
  c = "Je hebt de oude wegen geleerd, $N. Daarom geef ik je een geschenk uit de tijd dat ik zelf $C was.",
  g = { {"draak", "dragon, drake"}, {"jacht", "hunt"}, {"tand", "tooth"}, {"vijanden", "enemies (vijand)"}, {"vernietigen", "to destroy"}, {"staat voor", "represents (staan voor)"}, {"gezelschap", "company"}, {"geschenk", "gift"} },
