[8233] = { en = "A Simple Request", tier = 4,
  t = "Een eenvoudig verzoek",
  d = "Lord Jorach Ravenholdt wil je spreken. Het is een geheime zaak, en meer kan ik niet zeggen.$b$bRavenholdt Manor ligt in de Hillsbrad Foothills. Zoek een pad in de bergen ten noordwesten van Durnhold Keep.",
  o = "Spreek met Lord Jorach Ravenholdt in Ravenholdt Manor.",
  c = "Welkom, welkom, welkom! Ga toch zitten, $N, en laten we een eenvoudige zaak bespreken.$B$BWeet je, $N, ik ben onlangs iets kwijtgeraakt dat me dierbaar is. Om het maar eerlijk te zeggen: ik wil het terug, wat het ook kost. Er zit ook iets voor jou in, maak je daar geen zorgen over! O ja, iets heel moois.$B$BNu, wat zeg je ervan, $N... heb je zin in een avontuur?",
  g = { {"verzoek", "request"}, {"zaak", "matter, affair"}, {"bespreken", "to discuss"}, {"onlangs", "recently"}, {"kwijtgeraakt", "lost (kwijtraken)"}, {"dierbaar", "dear, precious"}, {"wat het ook kost", "at all costs"}, {"zorgen", "worries (zorg); maak je geen zorgen = don't worry"}, {"avontuur", "adventure"} },
