[8234] = { en = "Sealed Azure Bag", tier = 4,
  t = "Verzegelde azuurblauwe tas",
  d = "Eerst het belangrijkste. Wat ik kwijt ben, is een kleine blauwe tas. Wat erin zit, is een privézaak.$b$bJe hoeft de dieven niet achterna te gaan, want ze zijn al dood. Wat we wel weten: die dwazen kregen de tas niet open. Daarom verkochten ze hem als heilig relikwie aan een Timbermaw-sjamaan in Azshara. Slim.$b$bIk wil dat je naar Azshara reist en de tas van de sjamaan terughaalt, met list... of met geweld. Met de eerste manier heb je volgens mij meer kans. Als je hem hebt, breng hem dan naar Archmage Xylem.",
  o = "Haal de Sealed Azure Bag terug van de Timbermaw Shaman in Azshara. Breng de tas daarna naar Archmage Xylem, die ook in Azshara is.",
  p = "Ken ik jou?",
  c = "Ik zie dat je de tas van Lord Ravenholdt hebt. Waarom zei je dat niet meteen, jongen?",
  g = { {"verzegelde", "sealed (verzegeld)"}, {"azuurblauwe", "azure (azuurblauw)"}, {"privézaak", "private matter"}, {"dieven", "thieves (dief)"}, {"achterna te gaan", "to go after (achternagaan)"}, {"dwazen", "fools (dwaas)"}, {"relikwie", "relic"}, {"sjamaan", "shaman"}, {"terughaalt", "retrieve (terughalen)"}, {"list", "cunning, subtlety"}, {"geweld", "force, violence"}, {"kans", "chance"} },
},

[8235] = { en = "Encoded Fragments", tier = 4,
  t = "Gecodeerde fragmenten",
  d = "Lord Ravenholdt heeft ons allebei om een gunst gevraagd. Hij wil de betovering van deze tas laten verwijderen.$b$bHelaas zijn onlangs een paar van mijn boeken over het opheffen van betoveringen gestolen. Daarna werden ze door wilden vernietigd. De resten van mijn boeken zijn nog steeds waardevol voor mij.$b$bAls je genoeg gecodeerde fragmenten brengt, kan ik ze weer aan elkaar zetten. Je beste kans is om de beesten van Azshara te doden. Ze rapen namelijk zo'n beetje alles op.",
  o = "Breng 10 Encoded Fragments naar Archmage Xylem in Azshara.",
  p = "Heb je genoeg fragmenten gevonden zodat ik verder kan met mijn werk?",
  c = "Het lijkt erop dat je een paar van de betere fragmenten hebt gevonden. Misschien ben je toch niet waardeloos.",
  g = { {"gecodeerde", "encoded (gecodeerd)"}, {"gunst", "favour"}, {"betovering", "enchantment"}, {"verwijderen", "to remove"}, {"helaas", "unfortunately"}, {"opheffen", "dispelling, lifting"}, {"wilden", "savages (wilde)"}, {"vernietigd", "destroyed (vernietigen)"}, {"resten", "remains (rest)"}, {"waardevol", "valuable"}, {"aan elkaar zetten", "to piece together"}, {"rapen", "pick (up) (oprapen)"}, {"waardeloos", "worthless"} },
},

[8236] = { en = "The Azure Key", tier = 4,
  t = "De azuurblauwe sleutel",
  d = "Het zal even duren om de fragmenten te ontcijferen en de betovering weg te halen. Als ik klaar ben, breng ik de tas zelf naar Lord Ravenholdt.$b$bEr is nog de kwestie van de sleutel. Men zegt dat een groene draak die Morphaz heet hem heeft. De draak woont diep in de Temple of Atal'Hakkar. De ingang ligt in de Swamp of Sorrows.$b$bVerzamel je vrienden en ga naar zijn hol. Lord Ravenholdt wacht op je terugkeer met de sleutel.",
  o = "Breng de Azure Key terug naar Lord Jorach Ravenholdt.",
  p = "De tas is al aangekomen van Archmage Xylem. Heb je de sleutel gevonden?",
  c = "De sleutel! Ik dacht dat ik hem voor altijd kwijt was. Alsjeblieft, neem een betoverd kledingstuk uit mijn voorraad. Ze zijn alleen voor schurken met uitzonderlijke vaardigheid en trouw. Laat het bekend zijn dat er met $N niet te spotten valt!$B$B<Jorach opent de tas en een gouden gloed van binnenuit straalt over hem heen. Zijn ogen worden groot en hij staart...>",
  g = { {"sleutel", "key"}, {"even duren", "to take some time"}, {"ontcijferen", "to decipher"}, {"kwestie", "matter, question"}, {"hol", "lair, den"}, {"terugkeer", "return"}, {"kledingstuk", "garment"}, {"voorraad", "stores, supply"}, {"schurken", "rogues (schurk)"}, {"uitzonderlijke", "exceptional (uitzonderlijk)"}, {"trouw", "loyalty"}, {"niet te spotten valt", "is not to be trifled with"}, {"gloed", "glow"}, {"staart", "stares (staren)"} },
},

[8250] = { en = "Magecraft", tier = 4,
  t = "Magiërskunst",
  d = "Archmage Xylem vraagt de laatste tijd rond... naar iemand met jouw ervaring.$b$bAls je hem wilt opzoeken, vind je hem in Azshara. Zijn toren staat hoog boven op de kliffen. De enige weg naar boven is een teleportatiespreuk van zijn arrogante dienaar, Sanath Lim-yo.$b$bSanath heeft zijn kamp onder de toren van zijn meester. Om hem te vinden, reis je naar de plek waar de grote weg van Azshara zich splitst, bij de ingang van de Ruins of Eldarath. Ga vanaf die plek recht naar het noorden tot je bij de kliffen bent.",
  o = "Zoek Sanath Lim-yo op en krijg toegang tot Archmage Xylem.",
  c = "<Sanath kijkt je spottend aan.>$B$BAarts$c Xylem wacht op je komst.",
  g = { {"magiërskunst", "magecraft"}, {"vraagt", "asks (rondvragen: to ask around)"}, {"toren", "tower"}, {"teleportatiespreuk", "teleport spell"}, {"arrogante", "arrogant (arrogant)"}, {"dienaar", "servant"}, {"meester", "master"}, {"zich splitst", "forks, splits (zich splitsen)"}, {"recht", "straight, directly"}, {"toegang", "access, passage"}, {"spottend", "sneering, mocking"}, {"komst", "arrival"} },
},

[8251] = { en = "Magic Dust", tier = 4,
  t = "Magisch stof",
  d = "De bloedelfen in Azshara hebben een manier gevonden om de magische voorwerpen die ze krijgen tot poeder te malen. Het glinsterende stof dat ze maken, is anders dan de ingrediënten die je meestal krijgt met een spreuk om voorwerpen te ontleden.$b$bToen ik mijn leerling stuurde om het stof te ruilen, werd hij zonder aarzelen gedood. Daarvoor moeten ze boeten.$b$bDe tijd voor praten is voorbij, $N. Zoek de bloedelfen langs de kliffen van Azshara. Gebruik 'overtuigendere' methodes om hun glinsterende stof te krijgen.",
  o = "Breng 10 Glittering Dust naar Archmage Xylem.",
  p = "Heb je het stof?",
  c = "Goed gedaan, $N! Het blijft me verbazen hoe overtuigend een regen van arcane projectielen kan zijn.",
  g = { {"stof", "dust"}, {"bloedelfen", "blood elves (bloedelf)"}, {"voorwerpen", "items, objects (voorwerp)"}, {"tot poeder te malen", "to grind into powder"}, {"glinsterende", "glittering (glinsterend)"}, {"ontleden", "to break down, to disenchant"}, {"leerling", "apprentice, pupil"}, {"ruilen", "to trade"}, {"zonder aarzelen", "without hesitation"}, {"boeten", "to pay (for), to atone"}, {"overtuigendere", "more persuasive (overtuigend)"}, {"verbazen", "to amaze"}, {"projectielen", "missiles, projectiles (projectiel)"} },
},

[8252] = { en = "The Siren's Coral", tier = 4,
  t = "Het koraal van de sirene",
  d = "Kijk eens om je heen. De ruïnes en stranden worden overspoeld door de spitelash. Sinds kort hebben die ellendige wezens geleerd om de zeldzame ingrediënten te herkennen die alleen in Azshara voorkomen.$b$bIk heb het over betoverd koraal. Ze worden erdoor aangetrokken, maar ik weet niet waarom. Nu is er nog maar weinig koraal over in de baai, en dat is heel belangrijk voor mijn onderzoek. Ik wil dat je wat betoverd koraal afpakt van de spitelash-sirenes en het naar mij brengt.",
  o = "Verzamel 6 Enchanted Coral en breng ze terug naar Archmage Xylem.",
  p = "De spitelash-sirenes zijn verrassend bekwame magiërs. Maar niet zo bekwaam als jij, hoop ik?",
  c = "Dit is een prachtig stuk koraal, $N. Je vaardigheden zijn zonder twijfel precies en dodelijk.$B$BDenk niet dat niemand je inspanningen heeft gezien. Misschien ben je een echte test van je vaardigheden waard...",
  g = { {"koraal", "coral"}, {"sirene", "siren"}, {"ruïnes", "ruins (ruïne)"}, {"overspoeld", "overrun, flooded (overspoelen)"}, {"ellendige", "wretched (ellendig)"}, {"zeldzame", "rare (zeldzaam)"}, {"herkennen", "to recognize"}, {"betoverd", "enchanted"}, {"aangetrokken", "attracted, drawn (aantrekken)"}, {"baai", "bay"}, {"onderzoek", "research"}, {"bekwame", "skilled, adept (bekwaam)"}, {"vaardigheden", "skills (vaardigheid)"}, {"dodelijk", "deadly"}, {"inspanningen", "efforts (inspanning)"} },
},

[8253] = { en = "Destroy Morphaz", tier = 4,
  t = "Vernietig Morphaz",
  d = "Diep in de gezonken tempel van Atal'Hakkar woont een groene draak die Morphaz heet.$b$bJaren geleden overviel hij me in een brutale hinderlaag. Hij slokte mijn leerling in één keer op. Het verlies van een leerling is voor mij niet nieuw, maar deze leerling had een arcane scherf bij zich die groter en beter was dan alle andere.$b$bJe moet machtige bondgenoten verzamelen en de tempel in gaan. Vernietig Morphaz en haal de arcane scherf uit zijn eeuwenoude maag.",
  o = "Haal de Arcane Shard bij Morphaz vandaan en ga terug naar Archmage Xylem.",
  p = "Heb je mijn oude aartsvijand gedood?",
  c = "Ongelooflijk. De scherf is gegroeid doordat hij in de lange jaren de energie van de draak heeft opgenomen.$B$BMeer kan ik nu niet van je vragen. Met deze scherf is mijn volledige kracht om het arcane te smeden teruggekomen. Mijn eerste creatie is voor jou, $N. Je hoeft alleen maar te kiezen...",
  g = { {"overviel", "ambushed, attacked (overvallen)"}, {"brutale", "bold, brazen (brutaal)"}, {"hinderlaag", "ambush"}, {"slokte", "swallowed (opslokken)"}, {"verlies", "loss"}, {"scherf", "shard"}, {"bondgenoten", "allies (bondgenoot)"}, {"eeuwenoude", "ageless, age-old (eeuwenoud)"}, {"maag", "stomach"}, {"aartsvijand", "nemesis, archenemy"}, {"ongelooflijk", "incredible"}, {"opgenomen", "absorbed (opnemen)"}, {"smeden", "to forge"}, {"creatie", "creation"} },
},

[8254] = { en = "Cenarion Aid", tier = 4,
  t = "Hulp voor de Cenarion Circle",
  d = "Het is de weg van het goddelijke om mensen in nood te helpen. Hoe je dat doet, is niet belangrijk. Alleen waarom je het doet, telt.$b$bDe Cenarion Circle heeft zo'n nood. Spreek met Ogtinc om hen in hun moeilijke situatie te helpen. Hij woont boven op de kliffen ten noordoosten van de Ruins of Eldarath in Azshara.",
  o = "Zoek Ogtinc op in Azshara.",
  c = "Door jouw komst valt er een last van mijn schouders. We hebben veel te doen.",
  g = { {"goddelijke", "the divine (goddelijk)"}, {"in nood", "in need"}, {"telt", "counts, matters (tellen)"}, {"moeilijke situatie", "plight"}, {"last", "burden, weight"}, {"schouders", "shoulders (schouder)"} },
},

[8255] = { en = "Of Coursers We Know", tier = 4,
  t = "Wat we weten over coursers",
  d = "De mosshoof coursers van Azshara zijn prachtige dieren die vroeger in Felwood leefden. Ze zijn van nature bestand tegen ziekte en gif. De verdorvenheid daar had geen invloed op hen. In hun oude wijsheid besloten ze gewoon om die zieke plek te verlaten.$b$bHet doet mijn hart pijn, maar ik moet je vragen om op deze machtige dieren te jagen. Verzamel vier klieren van coursers. Dat is het eerste ingrediënt voor een genezende zalf. Met die zalf gaan we Felwood genezen.",
  o = "Verzamel 4 Healthy Courser Glands en breng ze naar Ogtinc in Azshara. Ogtinc woont boven op de kliffen ten noordoosten van de Ruins of Eldarath.",
  p = "Je bent terug. Is het gelukt?",
  c = "Het is goed dat het goddelijke pad je naar ons heeft geleid, $N. Je geloof staat de taken die nodig zijn voor deze zalf niet in de weg.$B$BWeet je, de courser is heilig voor de Cenarion Circle. Als zij ze doden, om welke reden ook, hoe nodig ook, dan verzwakt dat hun geest.",
  g = { {"prachtige", "magnificent (prachtig)"}, {"van nature", "naturally, by nature"}, {"bestand tegen", "resistant to"}, {"gif", "poison"}, {"verdorvenheid", "corruption"}, {"invloed", "influence, effect"}, {"klieren", "glands (klier)"}, {"genezende", "healing, restorative (genezend)"}, {"zalf", "salve, ointment"}, {"geleid", "led (leiden)"}, {"geloof", "faith, beliefs"}, {"in de weg", "in the way (in de weg staan)"}, {"heilig", "sacred, holy"}, {"verzwakt", "weakens (verzwakken)"} },
},

[8256] = { en = "The Ichor of Undeath", tier = 4,
  t = "Het slijm van de ondood",
  d = "Voor deze genezende zalf gebruik je een eenvoudig recept: één deel gif, twee delen geneesmiddel. Je hebt één geneesmiddel al gevonden. Nu moet je het gif verzamelen.$b$bMachtige ondoden, zoals de achtergebleven highborne die door de Ruins of Eldarath dwalen, zitten soms zo vol kwaad dat het samenklontert tot een ziekelijk groenig slijm. Voor de levenden heet deze stof ichor van de ondood.$b$bOmdat dit gemene goedje zo sterk is, heb ik maar één ichor nodig.",
  o = "Haal een Ichor of Undeath voor Ogtinc in Azshara. Ogtinc woont boven op de kliffen ten noordoosten van de Ruins of Eldarath.",
  p = "We moeten snel aan het ichor komen. Heb je het gevonden?",
  c = "Ik kan niet zeggen dat ik blij ben met zo'n walgelijke stof, maar het is een noodzakelijk kwaad. Dank je, $N.",
  g = { {"slijm", "goo, slime"}, {"ondood", "undeath; undead"}, {"recept", "formula, recipe"}, {"geneesmiddel", "cure, remedy"}, {"achtergebleven", "lingering, left behind"}, {"dwalen", "wander (dwalen)"}, {"samenklontert", "coalesces, clots (samenklonteren)"}, {"ziekelijk", "sickly"}, {"groenig", "greenish"}, {"gemene", "vile, nasty (gemeen)"}, {"goedje", "stuff, substance"}, {"walgelijke", "wretched, disgusting (walgelijk)"}, {"noodzakelijk kwaad", "necessary evil"} },
},

[8257] = { en = "Blood of Morphaz", tier = 4,
  t = "Het bloed van Morphaz",
  d = "Nu het laatste deel, het tweede geneesmiddel.$b$bMen weet dat de groene draak Morphaz immuun is voor alle soorten gif en ziekte. Veel druïden zijn gestorven om ons deze informatie te geven. Zijn bloed is zonder twijfel krachtig genoeg voor wat wij nodig hebben.$b$bEen koerier van de Cenarion Circle neemt de delen mee die je al hebt verzameld, terwijl jij het laatste deel haalt. Roep je bondgenoten bij elkaar en zoek het hol van de draak in de gezonken tempel van Atal'Hakkar. Breng zijn bloed naar Greta Mosshoof in Felwood.",
  o = "Dood Morphaz in de gezonken tempel van Atal'Hakkar en breng zijn bloed naar Greta Mosshoof in Felwood. De ingang van de gezonken tempel ligt in de Swamp of Sorrows.",
  p = "Heb je het bloed van Morphaz?",
  c = "Je hebt Morphaz gedood en zijn bloed naar ons gebracht... Ik kan dit goede nieuws bijna niet geloven!$B$BWe voegen de ingrediënten meteen samen en beginnen met het genezen van de bomen en dieren van Felwood. Het zal een heel leven duren om ongedaan te maken wat hier is gebeurd, maar jij hebt ons de middelen gegeven om het te doen.",
  g = { {"immuun", "immune"}, {"gestorven", "died (sterven)"}, {"krachtig", "potent, powerful"}, {"koerier", "courier"}, {"bij elkaar", "together (bij elkaar roepen: to summon)"}, {"voegen", "combine (samenvoegen)"}, {"genezen", "healing; to heal"}, {"ongedaan te maken", "to undo (ongedaan maken)"}, {"middelen", "means (middel)"} },
},

[8414] = { en = "Dispelling Evil", tier = 4,
  t = "Het kwaad verdrijven",
  d = "Gegroet, $c. Kruisvaarders zoals jij zijn een welkom gezicht in deze verlaten streken.$b$bWe hebben je heilige kracht nodig in de strijd tegen de eindeloze ondoden hier. Verzamel een groot aantal scourgestones en breng ze naar High Priest Thel'danis. De hogepriester bewaakt Uther's Tomb op Sorrow Hill, niet ver hiervandaan.$b$bAlleen iemand met een Argent Dawn Commission kan scourgestones vinden. Spreek dus met Officer Pureheart als je dat nog niet gedaan hebt.",
  o = "Verzamel 20 Minion's Scourgestones en breng ze naar High Priest Thel'danis in de Western Plaguelands.",
  p = "Welk kwaad heb je me gebracht?",
  c = "Het is riskant om het kwaad uit een scourgestone te verdrijven. Het trekt namelijk de aandacht van ondoden over ontelbare mijlen. Maar je bent sterk in het Licht, $n, en ik ben niet bang voor je...",
  g = { {"verdrijven", "to dispel, to drive out"}, {"gegroet", "greetings"}, {"kruisvaarders", "crusaders (kruisvaarder)"}, {"verlaten", "desolate, deserted"}, {"streken", "reaches, regions (streek)"}, {"eindeloze", "endless (eindeloos)"}, {"hogepriester", "high priest"}, {"bewaakt", "guards (bewaken)"}, {"riskant", "risky"}, {"aandacht", "attention"}, {"ontelbare", "countless (ontelbaar)"}, {"mijlen", "miles (mijl)"} },
},

[8416] = { en = "Inert Scourgestones", tier = 4,
  t = "Onwerkzame scourgestones",
  d = "Het kwaad is uit de stenen gezuiverd, $n.$b$bIk ken de plannen van Commander Ashlam. Hij heeft maar één onwerkzame steen nodig. Breng die naar hem, zodat we de Scourge in rechtvaardig vuur kunnen baden.",
  o = "Breng de Inert Scourgestone naar Commander Ashlam Valorfist in Chillwind Point.",
  p = "Kon Thel'danis de scourgestones reinigen?",
  c = "Je hebt gedaan wat ik vroeg, zonder vragen te stellen, $n.$b$bHet vertrouwen is er, zo lijkt het. Misschien kan ik je ons plan nu uitgebreider vertellen.",
  g = { {"onwerkzame", "inert (onwerkzaam)"}, {"gezuiverd", "purged, purified (zuiveren)"}, {"rechtvaardig", "righteous"}, {"baden", "to bathe"}, {"reinigen", "to cleanse"}, {"vertrouwen", "trust"}, {"uitgebreider", "in more detail (uitgebreid)"} },
},

[8419] = { en = "An Imp's Request", tier = 4,
  t = "Het verzoek van een imp",
  d = "$n, een imp in Felwood die Impsy heet, wil je spreken. Het is een beetje vreemd, want hij vraagt of je een stuk felcloth meebrengt als teken van goede wil. Je hebt als heksenmeester al veel macht, dus ik neem aan dat je weet dat de saters van Felwood dit felcloth bij zich hebben.$b$bJe vindt Impsy net ten noorden van de Bloodvenom Falls. Ik heb gehoord dat het daar in deze tijd van het jaar heel mooi is.",
  o = "Breng een stuk felcloth naar Impsy in Felwood.",
  p = "Heb je mijn felcloth?",
  c = "Wat ben jij een geweldige $C!$B$B<Impsy houdt het felcloth tegen zijn gezicht.>$B$BO, wat vind ik het heerlijk om te voelen. Hoe het je huid brandt en kwade gedachten door je hoofd weeft...",
  g = { {"vreemd", "strange"}, {"teken van goede wil", "sign of good faith"}, {"heksenmeester", "warlock"}, {"macht", "power"}, {"neem aan", "assume (aannemen)"}, {"saters", "satyrs (sater)"}, {"heerlijk", "lovely, wonderful"}, {"huid", "skin"}, {"kwade", "evil (kwaad)"}, {"gedachten", "thoughts (gedachte)"}, {"weeft", "weaves (weven)"} },
},

[8420] = { en = "Hot and Itchy", tier = 4,
  t = "Heet en jeukerig",
  d = "Misschien klinkt het vreemd uit de mond van een imp, maar ik wil graag een eigen huisdier. Echt waar. Het is gewoon niet eerlijk dat Niby mij heeft en ik niks!$b$bHet hoeft zelfs geen levend huisdier te zijn. Ik heb alleen iets nodig om mee te beginnen, zoals wat felcloth. De saters hier in Felwood hebben soms felcloth. Je moet er dus gewoon genoeg doden tot je wat vindt. Dat klinkt niet zo erg, toch?",
  o = "Breng een stuk felcloth naar Impsy in Felwood.",
  p = "Heb je mijn felcloth?",
  c = "Wauw! Je bent veel te aardig. Zeker voor een $C!$B$B<Impsy houdt het felcloth tegen zijn gezicht.>$B$BO, wat vind ik het heerlijk om te voelen. Hoe het je huid brandt en kwade gedachten door je hoofd weeft...",
  g = { {"jeukerig", "itchy"}, {"klinkt", "sounds (klinken)"}, {"huisdier", "pet"}, {"eerlijk", "fair"}, {"levend", "living, alive"}, {"erg", "bad"}, {"aardig", "kind, nice"} },
},

[8421] = { en = "The Wrong Stuff", tier = 4,
  t = "De verkeerde spullen",
  d = "Nu ik mijn felcloth heb, kan ik echt beginnen met het maken van *mijn* huisdier.$b$bHet heeft wel ogen nodig. Misschien kun je wat rottend hout van het Irontree-volk voor me afrukken, zodat ik er mooie ogen uit kan snijden. Ze zitten in het noorden, in de Irontree Woods.$b$bIk heb ook wat bloodvenom-essence nodig om het die nieuwe-demonengeur te geven. De besmette slijmwezens hebben die essence. Ze hangen hier vlakbij rond, bij Niby en mij.",
  o = "Breng 10 Rotting Wood en 4 Bloodvenom Essence naar Impsy in Felwood.",
  p = "Heb je de spullen?",
  c = "Hiermee gaat het heel goed lukken.",
  g = { {"verkeerde", "wrong (verkeerd)"}, {"spullen", "stuff, goods"}, {"rottend", "rotting"}, {"afrukken", "to rip off"}, {"snijden", "to carve, to cut"}, {"essence", "essence (also: essentie)"}, {"demonengeur", "demon smell"}, {"besmette", "tainted, infected (besmet)"}, {"slijmwezens", "oozes (slijmwezen)"}, {"rond", "around (rondhangen: to hang out)"}, {"vlakbij", "close by"} },
},

[8423] = { en = "Warrior Kinship", tier = 4,
  t = "Verwantschap tussen krijgers",
  d = "<De held bekijkt je van top tot teen.>$b$bJe bent een $c, zonder twijfel. Ik wil je om een eervolle taak vragen, maar eerst moet ik je kracht testen.$b$bMen zegt dat Rexxar de scherpte van zijn zwaarden testte door een helboar met één snelle slag te doden. Nu ga ik jouw kracht testen door jou ze te laten doden.",
  o = "Dood 7 Helboar in de Blasted Lands en ga terug naar de Fallen Hero of the Horde.",
  p = "De brandende stekels van de helboar laten afschuwelijke littekens achter. Wees niet bang voor de pijn en de misvorming, krijger. Ze zijn niets vergeleken met de gevangenis waaraan ik vastzit.",
  c = "Ik heb geen bewijs nodig om te weten wat je hebt gedaan, $C. Ik zie de vastberadenheid in je gezicht gegrift.",
  g = { {"verwantschap", "kinship"}, {"van top tot teen", "from head to toe"}, {"zonder twijfel", "without doubt"}, {"eervolle", "honourable (eervol)"}, {"scherpte", "sharpness"}, {"slag", "strike, blow"}, {"stekels", "spines (stekel)"}, {"afschuwelijke", "horrific (afschuwelijk)"}, {"littekens", "scars (litteken)"}, {"misvorming", "disfigurement"}, {"vergeleken met", "compared to"}, {"vastzit", "am bound, am stuck (vastzitten)"}, {"bewijs", "proof"}, {"vastberadenheid", "determination"}, {"gegrift", "etched, engraved (griffen)"} },
},

[9051] = { en = "Toxic Test", tier = 4,
  t = "Een giftige test",
  d = "Het gif dat je me hielp maken, is voor een speciaal doel. Door de grote devilsaurs van de krater is jagen hier gevaarlijk, en het is moeilijk voor mij om te overleven. Zelfs als ik sterk genoeg was, zou het doden van een devilsaur alleen maar betekenen dat een andere zijn gebied overneemt.$b$bNeem deze vergiftigde stekel en steek hem diep in een levende devilsaur. Het gif zou het beest moeten kalmeren, maar ik weet niet hoe snel...",
  o = "Steek een Devilsaur met de Devilsaur Barb. Ga terug naar Torwa Pathfinder in Un'Goro Crater als je dit gedaan hebt.",
  p = "Is het je gelukt om het grote beest te kalmeren?",
  c = "Dank je, $N. Je bent dapper en wijs.$B$BVertel eens, hoe reageerde de devilsaur op het gif?",
  e = "Devilsaur gestoken met de stekel",
  g = { {"giftige", "toxic (giftig)"}, {"doel", "purpose"}, {"krater", "crater"}, {"overleven", "to survive"}, {"gebied", "territory, area"}, {"overneemt", "takes over (overnemen)"}, {"vergiftigde", "poisoned (vergiftigd)"}, {"stekel", "barb, spine"}, {"steek", "stab (steken)"}, {"kalmeren", "to pacify, to calm"}, {"wijs", "wise"}, {"reageerde", "reacted (reageren)"} },
},

[9052] = { en = "Bloodpetal Poison", tier = 4,
  t = "Bloodpetal-gif",
  d = "Ik wil je vragen om me te helpen een soort gif te maken. Daarmee wil ik een groot wezen kalmeren dat hier in de krater leeft. Het gif is niet dodelijk. Alleen de scherpe ogen van een $c kunnen de ingrediënten verzamelen.$b$bDe bloodcap-paddenstoelen groeien in de bloodpetal-scheuten, overal in de krater. Gorishi-angels komen van de insecten in en rond de Slithering Scar, in het zuiden van de krater.",
  o = "Verzamel 8 Bloodcap en 8 Gorishi Stings, en ga terug naar Torwa Pathfinder in Un'Goro Crater.",
  p = "Ben je geslaagd?",
  c = "Eindelijk de ingrediënten!$B$BMet de aarde van Un'Goro die ik heb verzameld, is het gif snel gemaakt...",
  g = { {"een soort", "a kind of, of sorts"}, {"wezen", "creature"}, {"paddenstoelen", "mushrooms (paddenstoel)"}, {"scheuten", "sprouts (scheut)"}, {"angels", "stings (angel)"}, {"insecten", "insects (insect)"}, {"eindelijk", "at last"}, {"aarde", "soil, earth"} },
},

[9063] = { en = "Torwa Pathfinder", tier = 4,
  t = "Torwa Pathfinder",
  d = "Een jager die Torwa Pathfinder heet, heeft om de hulp van een druïde gevraagd. Hij zei dat alleen wij de nodige vaardigheden en het respect voor de natuur hebben om hem te helpen.$b$bEr is een weg die Un'Goro Crater met de woestijn van Tanaris verbindt. Waar die weg de krater in gaat, vind je Torwa vlakbij.",
  o = "Spreek met Torwa Pathfinder in Un'Goro Crater.",
  c = "Je hebt een lange reis gemaakt om mij te ontmoeten, $C, en geen moment te vroeg.",
  g = { {"druïde", "druid"}, {"nodige", "necessary (nodig)"}, {"respect", "respect"}, {"woestijn", "desert"}, {"verbindt", "connects (verbinden)"}, {"ontmoeten", "to meet"}, {"geen moment te vroeg", "not a moment too soon"} },
},

[8424] = { en = "War on the Shadowsworn", tier = 4,
  t = "Oorlog tegen de Shadowsworn",
  d = "De Shadowsworn die maar in de Blasted Lands blijven, doen me veel pijn. Hun duistere rituelen en spreuken veroorzaken een kwelling die ik nooit heb gevoeld toen ik nog leefde.$b$bVia jou kan ik mijn eigen boodschap van pijn brengen. Ga op weg en breng mijn woede.",
  o = "Slacht de Shadowsworn af in de Blasted Lands en ga terug naar de Fallen Hero of the Horde.",
  p = "De Shadowsworn zijn niet makkelijk te verslaan, hè? Maar je bent een krijger. Je zult winnen, of sterven terwijl je het probeert.",
  c = "Je hebt mijn pijn al verzacht en me geëerd. Dank je, $C.",
  g = { {"duistere", "dark (duister)"}, {"rituelen", "rituals (ritueel)"}, {"veroorzaken", "to cause"}, {"kwelling", "agony, torment"}, {"boodschap", "message"}, {"woede", "wrath, rage"}, {"slacht", "slaughter (afslachten)"}, {"sterven", "to die, to perish"}, {"verzacht", "eased, subdued (verzachten)"}, {"geëerd", "honoured (eren)"} },
},

})

